@import url("https://fonts.googleapis.com/css2?family=Inter:ital,opsz,wght@0,14..32,100..900;1,14..32,100..900&display=swap");

@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  :root {
    /* ============================================
       THEME SYSTEM VARIABLES - DO NOT REMOVE
       These variables are required for the design system.
       You may change their VALUES but must keep all variables.
       ============================================ */

    /* Core colors */
    --background: 0 0% 100%;
    --foreground: 222.2 47.4% 11.2%;
    --muted: 210 40% 96.1%;
    --muted-foreground: 215.4 16.3% 46.9%;
    --popover: 0 0% 100%;
    --popover-foreground: 222.2 47.4% 11.2%;
    --border: 214.3 31.8% 91.4%;
    --input: 214.3 31.8% 91.4%;
    --card: 0 0% 100%;
    --card-foreground: 222.2 47.4% 11.2%;
    --primary: 222.2 47.4% 11.2%;
    --primary-foreground: 210 40% 98%;
    --secondary: 210 40% 96.1%;
    --secondary-foreground: 222.2 47.4% 11.2%;
    --accent: 210 40% 96.1%;
    --accent-foreground: 222.2 47.4% 11.2%;
    --destructive: 0 100% 50%;
    --destructive-foreground: 210 40% 98%;
    --ring: 215 20.2% 65.1%;

    /* Border radius */
    --radius: 0.5rem;

    /* Chart colors */
    --chart-1: 221 83% 53%;
    --chart-2: 212 95% 68%;
    --chart-3: 216 92% 60%;
    --chart-4: 210 98% 78%;
    --chart-5: 212 97% 87%;

    /* Sidebar */
    --sidebar-background: 0 0% 98%;
    --sidebar-foreground: 240 5.3% 26.1%;
    --sidebar-primary: 240 5.9% 10%;
    --sidebar-primary-foreground: 0 0% 98%;
    --sidebar-accent: 240 4.8% 95.9%;
    --sidebar-accent-foreground: 240 5.9% 10%;
    --sidebar-border: 220 13% 91%;
    --sidebar-ring: 217.2 91.2% 59.8%;

    /* Font families */
    --font-sans: 'Inter', 'Helvetica Neue', sans-serif;
    --font-mono: 'Courier New', monospace;

    /* Shadow configuration */
    --shadow-x: 0px;
    --shadow-y: 1px;
    --shadow-blur: 4px;
    --shadow-spread: 0px;
    --shadow-opacity: 0.2;
    --shadow-color: #000000;

    /* Computed shadows (derived from params above) */
    --shadow-2xs: var(--shadow-x) var(--shadow-y) color-mix(in srgb, var(--shadow-color) calc(var(--shadow-opacity) * 100%), transparent);
    --shadow-xs: var(--shadow-x) var(--shadow-y) var(--shadow-blur) var(--shadow-spread) color-mix(in srgb, var(--shadow-color) calc(var(--shadow-opacity) * 100%), transparent);
    --shadow-sm: var(--shadow-x) var(--shadow-y) calc(var(--shadow-blur) * 1.5) var(--shadow-spread) color-mix(in srgb, var(--shadow-color) calc(var(--shadow-opacity) * 100%), transparent);
    --shadow-md: calc(var(--shadow-x) * 2) calc(var(--shadow-y) * 2) calc(var(--shadow-blur) * 3) calc(var(--shadow-spread) - 1px) color-mix(in srgb, var(--shadow-color) calc(var(--shadow-opacity) * 100%), transparent);
    --shadow-lg: calc(var(--shadow-x) * 4) calc(var(--shadow-y) * 4) calc(var(--shadow-blur) * 5) calc(var(--shadow-spread) - 3px) color-mix(in srgb, var(--shadow-color) calc(var(--shadow-opacity) * 100%), transparent);
    --shadow-xl: calc(var(--shadow-x) * 6) calc(var(--shadow-y) * 6) calc(var(--shadow-blur) * 7) calc(var(--shadow-spread) - 5px) color-mix(in srgb, var(--shadow-color) calc(var(--shadow-opacity) * 100%), transparent);
    --shadow-2xl: calc(var(--shadow-x) * 8) calc(var(--shadow-y) * 8) calc(max(0px, var(--shadow-blur) * 9 - 8px)) calc(var(--shadow-spread) - 12px) color-mix(in srgb, var(--shadow-color) calc(var(--shadow-opacity) * 250%), transparent);
    --shadow: var(--shadow-md);

    /* Location type colors (match SVG pin colors) */
    --lib-color: 196 35% 46%;
    --make-color: 338 38% 52%;

    /* ============================================
       END THEME SYSTEM VARIABLES
       Custom CSS can be added below this line
       ============================================ */
  }

}

/* ── Pink theme — outside @layer so it always overrides base ── */
html.theme-pink {
  --background: 350 35% 97%;
  --foreground: 340 22% 16%;
  --muted: 340 28% 91%;
  --muted-foreground: 340 12% 50%;
  --popover: 350 35% 98%;
  --popover-foreground: 340 22% 16%;
  --border: 340 20% 84%;
  --input: 340 20% 84%;
  --card: 0 0% 100%;
  --card-foreground: 340 22% 16%;
  --primary: 338 55% 55%;
  --primary-foreground: 0 0% 100%;
  --secondary: 340 25% 91%;
  --secondary-foreground: 340 22% 16%;
  --accent: 350 40% 87%;
  --accent-foreground: 340 22% 16%;
  --destructive: 0 72% 52%;
  --destructive-foreground: 0 0% 100%;
  --ring: 338 55% 55%;
  --lib-color: 196 32% 44%;
  --make-color: 338 52% 52%;
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply font-sans antialiased bg-background text-foreground;
    overflow: hidden;
  }
}

/* Leaflet hover tooltip */
.fab-hover-tooltip {
  background: white !important;
  border: 1px solid rgba(0,0,0,0.08) !important;
  border-radius: 10px !important;
  box-shadow: 0 6px 20px rgba(0,0,0,0.14) !important;
  padding: 8px 13px !important;
  white-space: nowrap !important;
  pointer-events: none !important;
}
.fab-hover-tooltip::before {
  border-top-color: white !important;
}
.leaflet-tooltip-top.fab-hover-tooltip {
  margin-bottom: 6px;
}
.fab-tt-name { font-size: 12px; font-weight: 700; color: #1a1a2e; line-height: 1.3; }
.fab-tt-type { font-size: 10px; color: rgba(26,26,46,0.52); margin-top: 2px; font-weight: 500; }

/* Leaflet map fixes */
.leaflet-container {
  width: 100%;
  height: 100%;
  z-index: 0;
}
.leaflet-control-zoom {
  display: none !important;
}
.leaflet-control-attribution {
  font-size: 9px !important;
  opacity: 0.5;
  background: transparent !important;
  box-shadow: none !important;
}

