import { useRef, useLayoutEffect, useState } from 'react';
import { X, ChevronRight } from 'lucide-react';
import type { Location } from '@/data/locations';

const toHashtag = (cap: string) => '#' + cap.toLowerCase().replace(/[^a-z0-9]/g, '');

interface Props {
  location: Location;
  x: number;
  y: number;
  onClose: () => void;
  onTagClick: (cap: string) => void;
  onMoreInfo: () => void;
  selectedCaps: Set<string>;
}

export default function LocationCard({ location, x, y, onClose, onTagClick, onMoreInfo, selectedCaps }: Props) {
  const cardRef = useRef<HTMLDivElement>(null);
  const [pos, setPos] = useState<{ top: number; left: number } | null>(null);

  useLayoutEffect(() => {
    if (!cardRef.current) return;
    const w = cardRef.current.offsetWidth;
    const h = cardRef.current.offsetHeight;
    const top = Math.max(8, Math.min(y - h - 62, window.innerHeight - h - 16));
    const left = Math.max(8, Math.min(x - w / 2, window.innerWidth - w - 8));
    setPos({ top, left });
  }, [x, y, location]);

  const isLib = location.type === 'Library';
  const colorVar = isLib ? '--lib-color' : '--make-color';
  const pinColor = `hsl(var(${colorVar}))`;

  return (
    <div
      ref={cardRef}
      onClick={e => e.stopPropagation()}
      style={{
        position: 'absolute', zIndex: 1001,
        top: pos ? pos.top : y - 260, left: pos ? pos.left : x - 120,
        visibility: pos ? 'visible' : 'hidden', width: 252,
      }}
    >
      <div className="rounded-2xl shadow-xl overflow-hidden bg-card border border-border/40">
        {/* Colored header */}
        <div className="px-4 pt-3 pb-2.5 flex items-start justify-between gap-2" style={{ background: pinColor }}>
          <div>
            <p className="text-white/70 text-[9px] font-bold uppercase tracking-widest">{location.type}</p>
            <h2 className="text-white font-bold text-sm leading-tight mt-0.5">{location.name}</h2>
          </div>
          <button onClick={onClose} className="text-white/60 hover:text-white flex-shrink-0 mt-1">
            <X size={14} />
          </button>
        </div>

        {/* Body */}
        <div className="px-3 py-2.5 space-y-2.5">
          {/* Clickable hashtag tags */}
          {(location.capabilities?.length ?? 0) > 0 && (
            <div className="flex flex-wrap gap-1">
              {location.capabilities!.map(cap => {
                const active = selectedCaps.has(cap);
                return (
                  <button
                    key={cap}
                    onClick={() => onTagClick(cap)}
                    className={`text-[10px] font-mono px-2 py-0.5 rounded-full border transition-all ${
                      active
                        ? 'bg-foreground text-background border-foreground'
                        : 'bg-muted text-foreground/65 border-transparent hover:border-foreground/20'
                    }`}
                  >
                    {toHashtag(cap)}
                  </button>
                );
              })}
            </div>
          )}

          {location.membershipCost && (
            <p className="text-[11px] text-muted-foreground leading-tight">
              <span className="font-semibold text-foreground">Access:</span> {location.membershipCost}
            </p>
          )}

          {/* More info → opens drawer */}
          <button
            onClick={onMoreInfo}
            className="flex items-center gap-1 text-[11px] font-semibold transition-opacity hover:opacity-70 w-full justify-end pt-0.5"
            style={{ color: pinColor }}
          >
            More info <ChevronRight size={12} />
          </button>
        </div>
      </div>

      {/* Triangle pointer */}
      <div className="flex justify-center">
        <div style={{ width: 0, height: 0, borderLeft: '8px solid transparent', borderRight: '8px solid transparent', borderTop: `10px solid ${pinColor}` }} />
      </div>
    </div>
  );
}

src/components/SuggestModal.tsx.content:
import { useState } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Label } from '@/components/ui/label';
import { Button } from '@/components/ui/button';
import { submitSuggestion } from 'zite-endpoints-sdk';
import { toast } from 'sonner';

interface Props {
  open: boolean;
  onClose: () => void;
}

export default function SuggestModal({ open, onClose }: Props) {
  const [form, setForm] = useState({ locationName: '', suggestedChange: '', sourceUrl: '', notes: '' });
  const [loading, setLoading] = useState(false);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    setForm(prev => ({ ...prev, [e.target.name]: e.target.value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!form.locationName || !form.suggestedChange || !form.sourceUrl) return;
    setLoading(true);
    try {
      await submitSuggestion(form);
      toast('Thanks! Your suggestion has been received.');
      setForm({ locationName: '', suggestedChange: '', sourceUrl: '', notes: '' });
      onClose();
    } catch {
      toast('Something went wrong. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={v => !v && onClose()}>
      <DialogContent className="max-w-md">
        <DialogHeader>
          <DialogTitle>Suggest a place</DialogTitle>
          <DialogDescription>
            Know a makerspace or library with fab equipment? Tell us — submissions are reviewed before being added.
          </DialogDescription>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4 mt-1">
          <div className="space-y-1.5">
            <Label htmlFor="locationName">Location name *</Label>
            <Input id="locationName" name="locationName" value={form.locationName} onChange={handleChange} placeholder="e.g. Noisebridge" required />
          </div>

          <div className="space-y-1.5">
            <Label htmlFor="suggestedChange">Suggested change *</Label>
            <Textarea id="suggestedChange" name="suggestedChange" value={form.suggestedChange} onChange={handleChange} placeholder="What's wrong or missing? e.g. They added a laser cutter in 2024" rows={3} required />
          </div>

          <div className="space-y-1.5">
            <Label htmlFor="sourceUrl">Source URL *</Label>
            <Input id="sourceUrl" name="sourceUrl" type="url" value={form.sourceUrl} onChange={handleChange} placeholder="https://..." required />
          </div>

          <div className="space-y-1.5">
            <Label htmlFor="notes">Notes <span className="text-muted-foreground">(optional)</span></Label>
            <Textarea id="notes" name="notes" value={form.notes} onChange={handleChange} placeholder="Anything else we should know..." rows={2} />
          </div>

          <div className="flex gap-2 justify-end pt-1">
            <Button type="button" variant="ghost" onClick={onClose}>Cancel</Button>
            <Button type="submit" disabled={loading}>
              {loading ? 'Sending…' : 'Submit'}
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}

