import { z } from 'zod';
import { createEndpoint, Locations } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  description: 'Returns all fabrication locations in SF',
  inputSchema: z.object({}),
  outputSchema: z.object({
    locations: z.array(z.object({
      id: z.string(),
      name: z.string().optional(),
      latitude: z.number().optional(),
      longitude: z.number().optional(),
      type: z.string().optional(),
      capabilities: z.array(z.string()).optional(),
      membershipCost: z.string().optional(),
      sourceLink: z.string().optional(),
      notes: z.string().optional(),
    })),
  }),
  execute: async () => {
    const { records } = await Locations.findAll({ limit: 500 });
    return { locations: records };
  },
});

import { z } from 'zod';
import { createEndpoint, Submissions } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  description: 'Stores a user suggestion for a new or updated location',
  inputSchema: z.object({
    locationName: z.string(),
    suggestedChange: z.string(),
    sourceUrl: z.string(),
    notes: z.string().optional(),
  }),
  outputSchema: z.object({ success: z.boolean() }),
  execute: async ({ input }) => {
    await Submissions.create({
      record: {
        locationName: input.locationName,
        suggestedChange: input.suggestedChange,
        sourceUrl: input.sourceUrl,
        notes: input.notes ?? '',
        submittedAt: new Date().toISOString(),
      },
    });
    return { success: true };
  },
});

import { useEffect, useRef, useState } from 'react';
import type { GetLocationsOutputType } from 'zite-endpoints-sdk';

type Location = GetLocationsOutputType['locations'][0];

interface Props {
  locations: Location[];
  onMarkerClick: (location: Location) => void;
  onMapClick: () => void;
}

let leafletReady = false;
const readyCallbacks: (() => void)[] = [];

function ensureLeaflet(cb: () => void) {
  if (leafletReady) { cb(); return; }
  readyCallbacks.push(cb);
  if (document.querySelector('#leaflet-js')) return;

  const link = document.createElement('link');
  link.id = 'leaflet-css';
  link.rel = 'stylesheet';
  link.href = 'https://unpkg.com/leaflet@1.9.4/dist/leaflet.css';
  document.head.appendChild(link);

  const script = document.createElement('script');
  script.id = 'leaflet-js';
  script.src = 'https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';
  script.onload = () => {
    leafletReady = true;
    readyCallbacks.forEach(fn => fn());
    readyCallbacks.length = 0;
  };
  document.head.appendChild(script);
}

const LIBRARY_COLOR = '#4A90D9';
const MAKERSPACE_COLOR = '#E07C3E';

function makeIcon(L: any, type: string) {
  const color = type === 'Library' ? LIBRARY_COLOR : MAKERSPACE_COLOR;
  return L.divIcon({
    className: '',
    html: `<div style="width:14px;height:14px;border-radius:50%;background:${color};border:2.5px solid white;box-shadow:0 2px 8px rgba(0,0,0,0.28);cursor:pointer;"></div>`,
    iconSize: [14, 14],
    iconAnchor: [7, 7],
  });
}

export default function MapView({ locations, onMarkerClick, onMapClick }: Props) {
  const containerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<any>(null);
  const markersRef = useRef<any[]>([]);
  const onMapClickRef = useRef(onMapClick);
  const onMarkerClickRef = useRef(onMarkerClick);
  const [leafletLoaded, setLeafletLoaded] = useState(leafletReady);

  useEffect(() => { onMapClickRef.current = onMapClick; }, [onMapClick]);
  useEffect(() => { onMarkerClickRef.current = onMarkerClick; }, [onMarkerClick]);

  useEffect(() => {
    ensureLeaflet(() => {
      setLeafletLoaded(true);
      if (mapRef.current || !containerRef.current) return;
      const L = (window as any).L;
      const map = L.map(containerRef.current, {
        center: [37.762, -122.435],
        zoom: 13,
        zoomControl: false,
      });
      L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
        attribution: '© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>',
        maxZoom: 19,
      }).addTo(map);
      L.control.zoom({ position: 'bottomright' }).addTo(map);
      map.on('click', () => onMapClickRef.current());
      mapRef.current = map;
    });
    return () => {
      if (mapRef.current) { mapRef.current.remove(); mapRef.current = null; }
    };
  }, []);

  useEffect(() => {
    if (!leafletLoaded || !mapRef.current) return;
    const L = (window as any).L;
    markersRef.current.forEach(m => m.remove());
    markersRef.current = [];
    locations.forEach(loc => {
      if (loc.latitude == null || loc.longitude == null) return;
      const marker = L.marker([loc.latitude, loc.longitude], {
        icon: makeIcon(L, loc.type ?? ''),
      });
      marker.on('click', (e: any) => {
        e.originalEvent?.stopPropagation();
        onMarkerClickRef.current(loc);
      });
      marker.addTo(mapRef.current);
      markersRef.current.push(marker);
    });
  }, [locations, leafletLoaded]);

  return <div ref={containerRef} className="w-full h-full" />;
}

import { X, ExternalLink } from 'lucide-react';
import type { GetLocationsOutputType } from 'zite-endpoints-sdk';

type Location = GetLocationsOutputType['locations'][0];

const CAPABILITY_COLORS: Record<string, string> = {
  '3D Printing': 'bg-violet-100 text-violet-700',
  'Resin Printing': 'bg-indigo-100 text-indigo-700',
  'CNC': 'bg-orange-100 text-orange-700',
  'PCB': 'bg-green-100 text-green-700',
