          <div className="flex items-center gap-2">
            <span className="inline-block w-3 h-3 rounded-full border-2 border-white shadow-sm flex-shrink-0"
              style={{ background: LIBRARY_COLOR }} />
            <span className="text-xs text-foreground">
              Library <span className="text-muted-foreground">({libraryCount})</span>
            </span>
          </div>
          <div className="flex items-center gap-2">
            <span className="inline-block w-3 h-3 rounded-full border-2 border-white shadow-sm flex-shrink-0"
              style={{ background: MAKERSPACE_COLOR }} />
