    <svg viewBox="0 0 30 40" width="20" height="27" xmlns="http://www.w3.org/2000/svg">
      <path d="M15 0C6.716 0 0 6.716 0 15C0 24.941 15 40 15 40C15 40 30 24.941 30 15C30 6.716 23.284 0 15 0Z" fill="#111"/>
