import { useEffect, useRef, useState } from 'react';
import type { GetLocationsOutputType } from 'zite-endpoints-sdk';

type Location = GetLocationsOutputType['locations'][0];

interface Props {
  locations: Location[];
  onMarkerClick: (location: Location) => void;
  onMapClick: () => void;
  onReady?: (map: any) => void;
}

let leafletReady = false;
const readyCallbacks: (() => void)[] = [];

function ensureLeaflet(cb: () => void) {
  if (leafletReady) { cb(); return; }
  readyCallbacks.push(cb);
  if (document.querySelector('#leaflet-js')) return;
  const link = document.createElement('link');
  link.id = 'leaflet-css';
  link.rel = 'stylesheet';
  link.href = 'https://unpkg.com/leaflet@1.9.4/dist/leaflet.css';
  document.head.appendChild(link);
  const script = document.createElement('script');
  script.id = 'leaflet-js';
  script.src = 'https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';
  script.onload = () => {
    leafletReady = true;
    readyCallbacks.forEach(fn => fn());
    readyCallbacks.length = 0;
  };
  document.head.appendChild(script);
}

// Lucide BookOpen paths for Library
const BOOK_OPEN = `<path d="M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z"/><path d="M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z"/>`;

// Lucide Wrench paths for Makerspace
const WRENCH = `<path d="M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z"/>`;

function makePinIcon(L: any, type: string) {
  const iconPaths = type === 'Library' ? BOOK_OPEN : WRENCH;
  // 30x40 teardrop, icon is 24x24 scaled 0.75 → 18x18, centered at (15,14)
  const svg = `
    <svg viewBox="0 0 30 40" width="30" height="40" xmlns="http://www.w3.org/2000/svg">
      <path d="M15 0C6.716 0 0 6.716 0 15C0 24.941 15 40 15 40C15 40 30 24.941 30 15C30 6.716 23.284 0 15 0Z" fill="#111111"/>
      <g transform="translate(6,5) scale(0.75)" stroke="white" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" fill="none">
        ${iconPaths}
      </g>
    </svg>`;
  return L.divIcon({
    className: '',
    html: svg,
    iconSize: [30, 40],
    iconAnchor: [15, 40],
  });
}

export default function MapView({ locations, onMarkerClick, onMapClick, onReady }: Props) {
  const containerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<any>(null);
  const markersRef = useRef<any[]>([]);
  const onMapClickRef = useRef(onMapClick);
  const onMarkerClickRef = useRef(onMarkerClick);
  const onReadyRef = useRef(onReady);
  const [leafletLoaded, setLeafletLoaded] = useState(leafletReady);

  useEffect(() => { onMapClickRef.current = onMapClick; }, [onMapClick]);
  useEffect(() => { onMarkerClickRef.current = onMarkerClick; }, [onMarkerClick]);
  useEffect(() => { onReadyRef.current = onReady; }, [onReady]);

  useEffect(() => {
    ensureLeaflet(() => {
      setLeafletLoaded(true);
      if (mapRef.current || !containerRef.current) return;
      const L = (window as any).L;
      const map = L.map(containerRef.current, {
        center: [37.762, -122.435],
        zoom: 13,
        zoomControl: false,
        attributionControl: true,
      });
      L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
        attribution: '© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>',
        maxZoom: 19,
      }).addTo(map);

      // Apply pink tint to tiles
      const tilePane = map.getPane('tilePane') as HTMLElement;
      if (tilePane) {
        tilePane.style.filter = 'hue-rotate(305deg) saturate(0.85) brightness(1.06) contrast(0.93)';
      }

      map.on('click', () => onMapClickRef.current());
      mapRef.current = map;
      onReadyRef.current?.(map);
    });
    return () => {
      if (mapRef.current) { mapRef.current.remove(); mapRef.current = null; }
    };
  }, []);

  useEffect(() => {
    if (!leafletLoaded || !mapRef.current) return;
    const L = (window as any).L;
    markersRef.current.forEach(m => m.remove());
    markersRef.current = [];
    locations.forEach(loc => {
      if (loc.latitude == null || loc.longitude == null) return;
      const marker = L.marker([loc.latitude, loc.longitude], {
        icon: makePinIcon(L, loc.type ?? ''),
      });
      marker.on('click', (e: any) => {
        e.originalEvent?.stopPropagation();
        onMarkerClickRef.current(loc);
      });
      marker.addTo(mapRef.current);
      markersRef.current.push(marker);
    });
  }, [locations, leafletLoaded]);

  return <div ref={containerRef} className="w-full h-full" />;
}

