import { useEffect, useRef, useState } from 'react';
import type { GetLocationsOutputType } from 'zite-endpoints-sdk';

type Location = GetLocationsOutputType['locations'][0];

interface Props {
  locations: Location[];
  onMarkerClick: (location: Location, x: number, y: number) => void;
  onMapClick: () => void;
  onReady?: (map: any) => void;
}

let leafletReady = false;
const readyCallbacks: (() => void)[] = [];

function ensureLeaflet(cb: () => void) {
  if (leafletReady) { cb(); return; }
  readyCallbacks.push(cb);
  if (document.querySelector('#leaflet-js')) return;
  const link = document.createElement('link');
  link.id = 'leaflet-css'; link.rel = 'stylesheet';
  link.href = 'https://unpkg.com/leaflet@1.9.4/dist/leaflet.css';
  document.head.appendChild(link);
  const script = document.createElement('script'); script.id = 'leaflet-js';
  script.src = 'https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';
  script.onload = () => { leafletReady = true; readyCallbacks.forEach(fn => fn()); readyCallbacks.length = 0; };
  document.head.appendChild(script);
}

// BookOpen paths for Library
const BOOK_SVG = `<path d="M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z"/><path d="M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z"/>`;
// Wrench paths for Makerspace
const WRENCH_SVG = `<path d="M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z"/>`;

// Pin colors: makerspace = deep rose, library = teal
const PIN_COLORS: Record<string, string> = {
  Library: '#4D8FA0',
  Makerspace: '#B85070',
};

function buildPinSvg(type: string) {
  const color = PIN_COLORS[type] ?? '#888';
  const icon = type === 'Library' ? BOOK_SVG : WRENCH_SVG;
  // 40×54 viewBox. Circle center (20,20) r11. Icon 24×24 → scale 0.58 ≈ 14px, translate(13,13)
  return `<svg viewBox="0 0 40 54" width="40" height="54" xmlns="http://www.w3.org/2000/svg">
    <ellipse cx="20" cy="52" rx="6" ry="2.5" fill="rgba(0,0,0,0.18)"/>
    <path d="M20 1C9.507 1 1 9.507 1 20C1 33 20 52 20 52C20 52 39 33 39 20C39 9.507 30.493 1 20 1Z" fill="${color}"/>
    <ellipse cx="14" cy="13" rx="7" ry="5" fill="rgba(255,255,255,0.18)"/>
    <circle cx="20" cy="20" r="11" fill="#F5C989"/>
    <g transform="translate(13,13) scale(0.583)" stroke="#2B1510" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" fill="none">${icon}</g>
  </svg>`;
}

function makeIcon(L: any, type: string) {
  return L.divIcon({
    className: '',
    html: buildPinSvg(type),
    iconSize: [40, 54],
    iconAnchor: [20, 52],
  });
}

export default function MapView({ locations, onMarkerClick, onMapClick, onReady }: Props) {
  const containerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<any>(null);
  const markersRef = useRef<any[]>([]);
  const onMapClickRef = useRef(onMapClick);
  const onMarkerClickRef = useRef(onMarkerClick);
  const onReadyRef = useRef(onReady);
  const [leafletLoaded, setLeafletLoaded] = useState(leafletReady);

  useEffect(() => { onMapClickRef.current = onMapClick; }, [onMapClick]);
  useEffect(() => { onMarkerClickRef.current = onMarkerClick; }, [onMarkerClick]);
  useEffect(() => { onReadyRef.current = onReady; }, [onReady]);

  useEffect(() => {
    ensureLeaflet(() => {
      setLeafletLoaded(true);
      if (mapRef.current || !containerRef.current) return;
      const L = (window as any).L;
      const map = L.map(containerRef.current, { center: [37.762, -122.435], zoom: 13, zoomControl: false });
      // CartoDB Positron — minimal, clean tiles
      L.tileLayer('https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png', {
        attribution: '© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> © <a href="https://carto.com/">CARTO</a>',
        maxZoom: 19,
      }).addTo(map);
      // Pink tint over the minimal base
      const tp = map.getPane('tilePane') as HTMLElement;
      if (tp) tp.style.filter = 'hue-rotate(305deg) saturate(1.1) brightness(1.06) contrast(0.92)';
      map.on('click', () => onMapClickRef.current());
      mapRef.current = map;
      onReadyRef.current?.(map);
    });
    return () => { if (mapRef.current) { mapRef.current.remove(); mapRef.current = null; } };
  }, []);

  useEffect(() => {
    if (!leafletLoaded || !mapRef.current) return;
    const L = (window as any).L;
    const map = mapRef.current;
    markersRef.current.forEach(m => m.remove());
    markersRef.current = [];
    locations.forEach(loc => {
      if (loc.latitude == null || loc.longitude == null) return;
      const marker = L.marker([loc.latitude, loc.longitude], { icon: makeIcon(L, loc.type ?? '') });
      // Hover: show name tooltip
      marker.bindTooltip(loc.name ?? '', {
        direction: 'top', offset: [0, -52], className: 'fab-hover-tooltip', sticky: false,
      });
      // Click: open detail card
      marker.on('click', (e: any) => {
        e.originalEvent?.stopPropagation();
        const pt = map.latLngToContainerPoint([loc.latitude, loc.longitude]);
        onMarkerClickRef.current(loc, pt.x, pt.y);
      });
      marker.addTo(map);
      markersRef.current.push(marker);
    });
  }, [locations, leafletLoaded]);

  return <div ref={containerRef} className="w-full h-full" />;
}

import { useRef, useLayoutEffect, useState } from 'react';
import { X, ExternalLink } from 'lucide-react';
import type { GetLocationsOutputType } from 'zite-endpoints-sdk';

type Location = GetLocationsOutputType['locations'][0];

const CAP_COLORS: Record<string, string> = {
  '3D Printing': '#7C3AED20|#7C3AED',
  'Resin Printing': '#4F46E520|#4F46E5',
  'CNC': '#EA580C20|#EA580C',
  'PCB': '#16A34A20|#16A34A',
  'Laser Cutting': '#DC262620|#DC2626',
  'Vinyl Cutting / Cricut': '#DB277720|#DB2777',
  'Electronics': '#0284C720|#0284C7',
  'Woodworking': '#D9770620|#D97706',
  'Sewing': '#E11D4820|#E11D48',
  'Embroidery': '#9333EA20|#9333EA',
};

function capStyle(cap: string) {
  const pair = CAP_COLORS[cap]?.split('|') ?? ['#88888820', '#888888'];
  return { background: pair[0], color: pair[1] };
}

interface Props {
  location: Location;
  x: number;
  y: number;
  onClose: () => void;
}

export default function LocationCard({ location, x, y, onClose }: Props) {
  const cardRef = useRef<HTMLDivElement>(null);
  const [pos, setPos] = useState<{ top: number; left: number } | null>(null);

  useLayoutEffect(() => {
    if (!cardRef.current) return;
    const w = cardRef.current.offsetWidth;
    const h = cardRef.current.offsetHeight;
    const vw = window.innerWidth;
    const vh = window.innerHeight;
    const top = Math.max(8, Math.min(y - h - 62, vh - h - 16));
    const left = Math.max(8, Math.min(x - w / 2, vw - w - 8));
    setPos({ top, left });
  }, [x, y, location]);

  const isLibrary = location.type === 'Library';
  const pinColor = isLibrary ? '#4D8FA0' : '#B85070';

  return (
    <div
      ref={cardRef}
      onClick={e => e.stopPropagation()}
      style={{
        position: 'absolute',
        zIndex: 1000,
        top: pos ? pos.top : y - 260,
        left: pos ? pos.left : x - 120,
        visibility: pos ? 'visible' : 'hidden',
        width: 240,
      }}
    >
      {/* Speech bubble */}
      <div className="rounded-2xl shadow-xl overflow-hidden" style={{ background: pinColor }}>
        <div className="px-4 pt-3 pb-1 flex items-start justify-between gap-2">
          <h2 className="text-white font-bold text-sm leading-tight">{location.name}</h2>
          <button onClick={onClose} className="text-white/70 hover:text-white flex-shrink-0 mt-0.5">
            <X size={14} />
          </button>
        </div>
        <div className="bg-white/95 mx-2 mb-2 rounded-xl px-3 py-2.5 space-y-2">
          <span className="text-[10px] font-bold uppercase tracking-widest" style={{ color: pinColor }}>
            {location.type}
          </span>
          {(location.capabilities?.length ?? 0) > 0 && (
            <div className="flex flex-wrap gap-1">
              {location.capabilities!.map(cap => (
                <span
                  key={cap}
                  className="text-[10px] font-semibold px-2 py-0.5 rounded-full"
                  style={capStyle(cap)}
                >
                  #{cap.toLowerCase().replace(/[^a-z0-9]/g, '')}
                </span>
              ))}
            </div>
          )}
          {location.membershipCost && (
            <p className="text-[11px] text-gray-600 leading-tight">
              <span className="font-semibold text-gray-800">Access:</span> {location.membershipCost}
            </p>
          )}
          {location.sourceLink && (
            <a href={location.sourceLink} target="_blank" rel="noopener noreferrer"
              className="inline-flex items-center gap-1 text-[10px] font-semibold underline underline-offset-2"
              style={{ color: pinColor }}>
              More info <ExternalLink size={9} />
            </a>
          )}
        </div>
      </div>
      {/* Triangle pointer */}
      <div className="flex justify-center -mt-px">
        <div style={{ width: 0, height: 0, borderLeft: '8px solid transparent', borderRight: '8px solid transparent', borderTop: `10px solid ${pinColor}` }} />
      </div>
    </div>
  );
}

import { useState, useEffect, useRef, useMemo } from 'react';
import MapView from '@/components/MapView';
import LocationCard from '@/components/LocationCard';
import SuggestModal from '@/components/SuggestModal';
import InfoPanel from '@/components/InfoPanel';
import { getLocations, GetLocationsOutputType } from 'zite-endpoints-sdk';
import { Toaster } from '@/components/ui/sonner';
import { Menu, Plus, ZoomIn, ZoomOut, Info, MapPin, X, Search } from 'lucide-react';

type Location = GetLocationsOutputType['locations'][0];

// SF ZIP code centroids
const SF_ZIPS: Record<string, [number, number]> = {
  '94102': [37.7798, -122.4194], '94103': [37.7726, -122.4118],
  '94105': [37.7899, -122.3940], '94107': [37.7612, -122.3955],
  '94108': [37.7918, -122.4069], '94109': [37.7942, -122.4209],
  '94110': [37.7490, -122.4150], '94112': [37.7218, -122.4401],
  '94114': [37.7607, -122.4350], '94115': [37.7862, -122.4430],
  '94116': [37.7442, -122.4850], '94117': [37.7699, -122.4469],
  '94118': [37.7799, -122.4617], '94121': [37.7770, -122.4934],
  '94122': [37.7583, -122.4942], '94123': [37.7996, -122.4385],
  '94124': [37.7283, -122.3896], '94127': [37.7367, -122.4581],
  '94131': [37.7440, -122.4380], '94132': [37.7218, -122.4762],
  '94133': [37.8007, -122.4094], '94134': [37.7135, -122.4043],
};

function haversineKm([lat1, lon1]: [number, number], [lat2, lon2]: [number, number]) {
  const R = 6371, dLat = (lat2 - lat1) * Math.PI / 180, dLon = (lon2 - lon1) * Math.PI / 180;
  const a = Math.sin(dLat / 2) ** 2 + Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) * Math.sin(dLon / 2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

const ALL_CAPS = ['3D Printing', 'Resin Printing', 'Laser Cutting', 'CNC', 'PCB', 'Vinyl Cutting / Cricut', 'Electronics', 'Woodworking', 'Sewing'];

function MapBtn({ onClick, children }: { onClick: () => void; children: React.ReactNode }) {
  return (
    <button onClick={onClick} className="w-10 h-10 border border-foreground/70 bg-background/90 backdrop-blur-sm flex items-center justify-center hover:bg-background transition-colors">
      {children}
    </button>
  );
}

export default function App() {
  const [locations, setLocations] = useState<Location[]>([]);
  const [selected, setSelected] = useState<{ location: Location; x: number; y: number } | null>(null);
  const [suggestOpen, setSuggestOpen] = useState(false);
  const [infoOpen, setInfoOpen] = useState(false);
  const [selectedCaps, setSelectedCaps] = useState<Set<string>>(new Set());
  const [zipInput, setZipInput] = useState('');
  const [activeZip, setActiveZip] = useState('');
  const [zipOpen, setZipOpen] = useState(false);
  const [zipError, setZipError] = useState('');
  const mapRef = useRef<any>(null);

  useEffect(() => { getLocations({}).then(d => setLocations(d.locations)).catch(() => {}); }, []);

  const filtered = useMemo(() => {
    let result = locations;
    if (selectedCaps.size > 0)
      result = result.filter(l => l.capabilities?.some(c => selectedCaps.has(c)));
    if (activeZip) {
      const center = SF_ZIPS[activeZip];
      if (center) result = result.filter(l => l.latitude && l.longitude && haversineKm(center, [l.latitude, l.longitude]) <= 2.5);
    }
    return result;
  }, [locations, selectedCaps, activeZip]);

  function toggleCap(cap: string) {
    setSelectedCaps(prev => { const s = new Set(prev); s.has(cap) ? s.delete(cap) : s.add(cap); return s; });
    setSelected(null);
  }

  function applyZip() {
    const z = zipInput.trim();
    if (!SF_ZIPS[z]) { setZipError('Not a valid SF ZIP code.'); return; }
    setZipError('');
    setActiveZip(z);
    const [lat, lng] = SF_ZIPS[z];
    mapRef.current?.setView([lat, lng], 15);
    setZipOpen(false);
    setSelected(null);
  }

  function clearZip() { setActiveZip(''); setZipInput(''); setZipError(''); }

  return (
    <div className="w-screen h-screen overflow-hidden relative bg-background">
      <MapView
        locations={filtered}
        onMarkerClick={(loc, x, y) => setSelected({ location: loc, x, y })}
        onMapClick={() => setSelected(null)}
        onReady={map => { mapRef.current = map; }}
      />

      {/* ── Top-left menu ── */}
      <div className="absolute top-4 left-4 z-[1000]">
        <MapBtn onClick={() => setInfoOpen(true)}><Menu size={17} strokeWidth={1.8} /></MapBtn>
      </div>

      {/* ── Top-center title ── */}
      <div className="absolute top-4 left-1/2 -translate-x-1/2 z-[1000] pointer-events-none select-none text-center">
        <h1 className="font-black uppercase leading-none tracking-tight text-foreground" style={{ fontSize: '1.3rem' }}>fabnetwork</h1>
        <p className="text-[9px] font-semibold tracking-widest uppercase text-foreground/50 mt-0.5">san francisco</p>
      </div>

      {/* ── Top-right suggest ── */}
      <div className="absolute top-4 right-4 z-[1000]">
        <MapBtn onClick={() => setSuggestOpen(true)}><Plus size={18} strokeWidth={1.8} /></MapBtn>
      </div>

      {/* ── Bottom-right controls ── */}
      <div className="absolute bottom-8 right-4 z-[1000] flex flex-col -space-y-px">
        <MapBtn onClick={() => mapRef.current?.zoomIn()}><ZoomIn size={15} strokeWidth={1.8} /></MapBtn>
        <MapBtn onClick={() => mapRef.current?.zoomOut()}><ZoomOut size={15} strokeWidth={1.8} /></MapBtn>
        <MapBtn onClick={() => setInfoOpen(true)}><Info size={15} strokeWidth={1.8} /></MapBtn>
      </div>

      {/* ── GPS / ZIP search ── */}
      <div className="absolute bottom-8 left-4 z-[1000] flex flex-col items-start gap-2">
        {zipOpen && (
          <div className="bg-background/95 backdrop-blur-sm border border-border rounded-xl p-3 shadow-lg w-52">
            <p className="text-[10px] font-semibold uppercase tracking-widest text-muted-foreground mb-2">Search by SF ZIP code</p>
            <div className="flex gap-1.5">
              <input
                className="flex-1 border border-border rounded-lg px-2.5 py-1.5 text-xs outline-none focus:ring-1 focus:ring-foreground/20 font-mono"
                placeholder="e.g. 94110"
                value={zipInput}
                onChange={e => { setZipInput(e.target.value); setZipError(''); }}
                onKeyDown={e => e.key === 'Enter' && applyZip()}
                maxLength={5}
                autoFocus
              />
              <button onClick={applyZip} className="bg-foreground text-background rounded-lg px-2.5 py-1.5 text-xs font-semibold hover:opacity-80 transition-opacity">Go</button>
            </div>
            {zipError && <p className="text-[10px] text-destructive mt-1.5">{zipError}</p>}
          </div>
        )}
        <div className="flex items-center gap-2">
          <MapBtn onClick={() => { setZipOpen(o => !o); setZipError(''); }}>
            <MapPin size={15} strokeWidth={1.8} className={activeZip ? 'text-primary' : ''} />
          </MapBtn>
          {activeZip && (
            <div className="flex items-center gap-1.5 bg-foreground text-background rounded-full px-2.5 py-1 text-xs font-semibold">
              {activeZip} <button onClick={clearZip}><X size={11} /></button>
            </div>
          )}
        </div>
      </div>

      {/* ── Capability filter chips ── */}
      <div className="absolute bottom-0 left-0 right-0 z-[999] pointer-events-none">
        <div className="pointer-events-auto px-3 pb-3 pt-2">
          <div className="flex gap-1.5 overflow-x-auto pb-0.5" style={{ scrollbarWidth: 'none' }}>
            {ALL_CAPS.map(cap => {
              const active = selectedCaps.has(cap);
              return (
                <button
                  key={cap}
                  onClick={() => toggleCap(cap)}
                  className={`flex-shrink-0 px-3 py-1.5 rounded-full text-[11px] font-semibold border transition-all whitespace-nowrap ${
                    active ? 'bg-foreground text-background border-foreground' : 'bg-background/88 backdrop-blur-sm text-foreground border-border hover:border-foreground/40'
                  }`}
                >
                  {cap}
                </button>
              );
            })}
            {selectedCaps.size > 0 && (
              <button onClick={() => { setSelectedCaps(new Set()); setSelected(null); }}
                className="flex-shrink-0 px-3 py-1.5 rounded-full text-[11px] font-semibold border border-destructive/40 text-destructive bg-background/88 backdrop-blur-sm hover:bg-destructive/10 transition-all whitespace-nowrap">
                Clear
              </button>
            )}
          </div>
        </div>
      </div>

      {/* ── Speech bubble card ── */}
      {selected && (
        <LocationCard location={selected.location} x={selected.x} y={selected.y} onClose={() => setSelected(null)} />
      )}

      <InfoPanel open={infoOpen} onClose={() => setInfoOpen(false)} onSuggest={() => { setInfoOpen(false); setSuggestOpen(true); }} />
      <SuggestModal open={suggestOpen} onClose={() => setSuggestOpen(false)} />
      <Toaster position="top-center" />
    </div>
  );
}

