    if (selectedCaps.size > 0)
      result = result.filter(l => l.capabilities?.some(c => selectedCaps.has(c)));
    if (activeZip) {
      const center = SF_ZIPS[activeZip];
      if (center) result = result.filter(l => l.latitude && l.longitude && haversineKm(center, [l.latitude, l.longitude]) <= 2.5);
    }
    return result;
  }, [locations, selectedCaps, activeZip]);

  function toggleCap(cap: string) {
    setSelectedCaps(prev => { const s = new Set(prev); s.has(cap) ? s.delete(cap) : s.add(cap); return s; });
    setSelected(null);
  }

  function applyZip() {
    const z = zipInput.trim();
    if (!SF_ZIPS[z]) { setZipError('Not a valid SF ZIP code.'); return; }
    setZipError('');
    setActiveZip(z);
    const [lat, lng] = SF_ZIPS[z];
    mapRef.current?.setView([lat, lng], 15);
    setZipOpen(false);
    setSelected(null);
  }

  function clearZip() { setActiveZip(''); setZipInput(''); setZipError(''); }

  return (
    <div className="w-screen h-screen overflow-hidden relative bg-background">
      <MapView
        locations={filtered}
        onMarkerClick={(loc, x, y) => setSelected({ location: loc, x, y })}
        onMapClick={() => setSelected(null)}
        onReady={map => { mapRef.current = map; }}
      />

      {/* ── Top-left menu ── */}
      <div className="absolute top-4 left-4 z-[1000]">
        <MapBtn onClick={() => setInfoOpen(true)}><Menu size={17} strokeWidth={1.8} /></MapBtn>
      </div>

      {/* ── Top-center title ── */}
      <div className="absolute top-4 left-1/2 -translate-x-1/2 z-[1000] pointer-events-none select-none text-center">
        <h1 className="font-black uppercase leading-none tracking-tight text-foreground" style={{ fontSize: '1.3rem' }}>fabnetwork</h1>
        <p className="text-[9px] font-semibold tracking-widest uppercase text-foreground/50 mt-0.5">san francisco</p>
      </div>

      {/* ── Top-right suggest ── */}
      <div className="absolute top-4 right-4 z-[1000]">
        <MapBtn onClick={() => setSuggestOpen(true)}><Plus size={18} strokeWidth={1.8} /></MapBtn>
      </div>

      {/* ── Bottom-right controls ── */}
      <div className="absolute bottom-8 right-4 z-[1000] flex flex-col -space-y-px">
        <MapBtn onClick={() => mapRef.current?.zoomIn()}><ZoomIn size={15} strokeWidth={1.8} /></MapBtn>
        <MapBtn onClick={() => mapRef.current?.zoomOut()}><ZoomOut size={15} strokeWidth={1.8} /></MapBtn>
        <MapBtn onClick={() => setInfoOpen(true)}><Info size={15} strokeWidth={1.8} /></MapBtn>
      </div>

      {/* ── GPS / ZIP search ── */}
      <div className="absolute bottom-8 left-4 z-[1000] flex flex-col items-start gap-2">
        {zipOpen && (
          <div className="bg-background/95 backdrop-blur-sm border border-border rounded-xl p-3 shadow-lg w-52">
            <p className="text-[10px] font-semibold uppercase tracking-widest text-muted-foreground mb-2">Search by SF ZIP code</p>
            <div className="flex gap-1.5">
              <input
                className="flex-1 border border-border rounded-lg px-2.5 py-1.5 text-xs outline-none focus:ring-1 focus:ring-foreground/20 font-mono"
                placeholder="e.g. 94110"
                value={zipInput}
                onChange={e => { setZipInput(e.target.value); setZipError(''); }}
                onKeyDown={e => e.key === 'Enter' && applyZip()}
                maxLength={5}
                autoFocus
              />
              <button onClick={applyZip} className="bg-foreground text-background rounded-lg px-2.5 py-1.5 text-xs font-semibold hover:opacity-80 transition-opacity">Go</button>
            </div>
            {zipError && <p className="text-[10px] text-destructive mt-1.5">{zipError}</p>}
          </div>
        )}
        <div className="flex items-center gap-2">
          <MapBtn onClick={() => { setZipOpen(o => !o); setZipError(''); }}>
            <MapPin size={15} strokeWidth={1.8} className={activeZip ? 'text-primary' : ''} />
          </MapBtn>
          {activeZip && (
            <div className="flex items-center gap-1.5 bg-foreground text-background rounded-full px-2.5 py-1 text-xs font-semibold">
              {activeZip} <button onClick={clearZip}><X size={11} /></button>
            </div>
          )}
        </div>
      </div>

      {/* ── Capability filter chips ── */}
      <div className="absolute bottom-0 left-0 right-0 z-[999] pointer-events-none">
        <div className="pointer-events-auto px-3 pb-3 pt-2">
          <div className="flex gap-1.5 overflow-x-auto pb-0.5" style={{ scrollbarWidth: 'none' }}>
            {ALL_CAPS.map(cap => {
              const active = selectedCaps.has(cap);
              return (
                <button
                  key={cap}
                  onClick={() => toggleCap(cap)}
                  className={`flex-shrink-0 px-3 py-1.5 rounded-full text-[11px] font-semibold border transition-all whitespace-nowrap ${
                    active ? 'bg-foreground text-background border-foreground' : 'bg-background/88 backdrop-blur-sm text-foreground border-border hover:border-foreground/40'
                  }`}
                >
                  {cap}
                </button>
              );
            })}
            {selectedCaps.size > 0 && (
              <button onClick={() => { setSelectedCaps(new Set()); setSelected(null); }}
                className="flex-shrink-0 px-3 py-1.5 rounded-full text-[11px] font-semibold border border-destructive/40 text-destructive bg-background/88 backdrop-blur-sm hover:bg-destructive/10 transition-all whitespace-nowrap">
                Clear
              </button>
            )}
          </div>
        </div>
      </div>

      {/* ── Speech bubble card ── */}
      {selected && (
        <LocationCard location={selected.location} x={selected.x} y={selected.y} onClose={() => setSelected(null)} />
      )}

      <InfoPanel open={infoOpen} onClose={() => setInfoOpen(false)} onSuggest={() => { setInfoOpen(false); setSuggestOpen(true); }} />
      <SuggestModal open={suggestOpen} onClose={() => setSuggestOpen(false)} />
      <Toaster position="top-center" />
    </div>
  );
}

import { useRef, useLayoutEffect, useState } from 'react';
import { X, ExternalLink } from 'lucide-react';
import type { GetLocationsOutputType } from 'zite-endpoints-sdk';

type Location = GetLocationsOutputType['locations'][0];

const CAP_COLORS: Record<string, string> = {
  '3D Printing': '#7C3AED20|#7C3AED',
  'Resin Printing': '#4F46E520|#4F46E5',
  'CNC': '#EA580C20|#EA580C',
  'PCB': '#16A34A20|#16A34A',
  'Laser Cutting': '#DC262620|#DC2626',
  'Vinyl Cutting / Cricut': '#DB277720|#DB2777',
  'Electronics': '#0284C720|#0284C7',
  'Woodworking': '#D9770620|#D97706',
  'Sewing': '#E11D4820|#E11D48',
  'Embroidery': '#9333EA20|#9333EA',
};

function capStyle(cap: string) {
  const pair = CAP_COLORS[cap]?.split('|') ?? ['#88888820', '#888888'];
  return { background: pair[0], color: pair[1] };
}

interface Props {
  location: Location;
  x: number;
  y: number;
  onClose: () => void;
}

export default function LocationCard({ location, x, y, onClose }: Props) {
  const cardRef = useRef<HTMLDivElement>(null);
  const [pos, setPos] = useState<{ top: number; left: number } | null>(null);

  useLayoutEffect(() => {
    if (!cardRef.current) return;
    const w = cardRef.current.offsetWidth;
    const h = cardRef.current.offsetHeight;
    const vw = window.innerWidth;
    const vh = window.innerHeight;
    const top = Math.max(8, Math.min(y - h - 62, vh - h - 16));
    const left = Math.max(8, Math.min(x - w / 2, vw - w - 8));
    setPos({ top, left });
  }, [x, y, location]);

  const isLibrary = location.type === 'Library';
  const pinColor = isLibrary ? '#4D8FA0' : '#B85070';

  return (
    <div
      ref={cardRef}
      onClick={e => e.stopPropagation()}
      style={{
        position: 'absolute',
        zIndex: 1000,
        top: pos ? pos.top : y - 260,
        left: pos ? pos.left : x - 120,
        visibility: pos ? 'visible' : 'hidden',
        width: 240,
      }}
    >
      {/* Speech bubble */}
      <div className="rounded-2xl shadow-xl overflow-hidden" style={{ background: pinColor }}>
        <div className="px-4 pt-3 pb-1 flex items-start justify-between gap-2">
          <h2 className="text-white font-bold text-sm leading-tight">{location.name}</h2>
          <button onClick={onClose} className="text-white/70 hover:text-white flex-shrink-0 mt-0.5">
            <X size={14} />
          </button>
        </div>
        <div className="bg-white/95 mx-2 mb-2 rounded-xl px-3 py-2.5 space-y-2">
          <span className="text-[10px] font-bold uppercase tracking-widest" style={{ color: pinColor }}>
            {location.type}
          </span>
          {(location.capabilities?.length ?? 0) > 0 && (
            <div className="flex flex-wrap gap-1">
              {location.capabilities!.map(cap => (
                <span
                  key={cap}
                  className="text-[10px] font-semibold px-2 py-0.5 rounded-full"
                  style={capStyle(cap)}
                >
                  #{cap.toLowerCase().replace(/[^a-z0-9]/g, '')}
                </span>
              ))}
            </div>
          )}
          {location.membershipCost && (
            <p className="text-[11px] text-gray-600 leading-tight">
              <span className="font-semibold text-gray-800">Access:</span> {location.membershipCost}
            </p>
          )}
          {location.sourceLink && (
            <a href={location.sourceLink} target="_blank" rel="noopener noreferrer"
              className="inline-flex items-center gap-1 text-[10px] font-semibold underline underline-offset-2"
              style={{ color: pinColor }}>
              More info <ExternalLink size={9} />
            </a>
          )}
        </div>
      </div>
      {/* Triangle pointer */}
      <div className="flex justify-center -mt-px">
        <div style={{ width: 0, height: 0, borderLeft: '8px solid transparent', borderRight: '8px solid transparent', borderTop: `10px solid ${pinColor}` }} />
      </div>
    </div>
  );
}

